    faq_a_glib_friends: "Un thème pour l'amitié et la chaleur humaine : nouer de nouvelles amitiés, écouter vraiment, renouer une ancienne amitié, recevoir des amis, un mot gentil chaque jour, et un sourire et un bonjour. Deux petites idées du thème viennent du classique de Dale Carnegie « Comment se faire des amis » – retenir les prénoms et s'intéresser sincèrement aux autres. Appuyez sur « + Coin lecture » sur la carte du livre pour l'ajouter au Coin lecture, dans « À lire » – et la carte disparaît alors des objectifs.",
