    bag_examples_v2_toast: "🎁 Nouveaux exemples dans votre sac : idées cadeaux, une liste pour l'hôtel et une pour l'avion ✨",
    faq_a_bag_examples_list: "Un nouveau sac arrive avec des exemples que vous pouvez modifier ou supprimer comme tout le reste : Maison (courses, recettes, repas de la semaine), Famille (petits moments, une liste pour la fête d'anniversaire, activités et cours), Idées (idées pour le week-end, idées cadeaux par catégorie, et que faire de l'argent économisé) et Voyages (endroits où vous voulez aller, valise pour le voyage, valise pour l'hôtel et une liste pour le vol à l'étranger). Un sac qui existait déjà reçoit une seule fois les plus récents, dans ses propres poches.",
    faq_q_bag_examples_list: "Quels exemples trouve-t-on dans Mon sac ?",
    faq_a_nm_me1_guide: "Sky – votre personnage dans New Me, dans sa première forme (Sky 1). La première fois, juste après l'inscription, un portail de lumière s'ouvre, entouré d'étincelles, et Sky en sort en volant, explique en quelques touchers ce qui vous attend, puis reste à côté de chaque question : pendant le choix des repas, il écrit avec vous dans son livre, et un toucher sur son conseil en montre un autre. À la fin, Sky fait la fête avec vous et vous emmène pour un petit tour – et quand le tour se termine, il partage encore un petit moment avec vous. Si vous partez au milieu – des questions ou du tour –, la prochaine fois, Sky est ravi de vous revoir et demande s'il faut reprendre au même endroit.",
    faq_q_nm_me1_guide: "Qui vous accompagne à l'entrée de New Me ?",
