    nm_m1_joy_btn: "Un petit tour",
    nm_m1_joy_text: "Votre menu vous attend, et le monde magique se réveille déjà.",
    nm_m1_joy_title: "Youpi! Tout est prêt",
    nm_m1_magic_text: "Et chacun de vos vrais pas en avant ouvre de nouveaux lieux dans le monde magique",
    nm_m1_menu_text: "Ensemble, nous allons composer un menu fait pour vous : des plats que vous aimez, aux heures qui vous conviennent.",
    nm_m1_portal: "Un nouveau monde s'ouvre",
    nm_m1_q_about: "Quel plaisir de vous rencontrer!",
    nm_m1_q_agree: "Avant de commencer – quelques mots importants",
    nm_m1_q_letter: "Des mots pour votre moi du futur? Je les garde précieusement pour vous",
    nm_m1_q_menu: "Écrivons les rêves ensemble – et réalisons-les ensemble",
    nm_m1_q_plan: "Vous pouvez changer à tout moment – ici, il n'y a pas de mauvais choix.",
    nm_m1_q_times: "Vos horaires sont aussi les miens",
    nm_m1_ready_text: "D'abord quelques petites questions – puis nous choisirons les repas ensemble.",
    nm_m1_skip: "Passer",
    nm_m1_tip_ai: "Un aliment qui n'est pas dans la liste ? Plus tard, dans « Changer », vous pourrez l'écrire avec vos propres mots – et l'IA fera le calcul. Et maintenant, choisissons ensemble ce qu'on mange chaque jour.",
    nm_m1_tip_love: "Et si quelque chose ne vous plaît pas – vous pouvez toujours le changer avec l'IA. Peu importe le plat – si vous l'aimez, il reste au menu.",
    nm_m1_tip_rice: "Ce que je préfère, c'est le riz – ce sera ma base, alors je vais le choisir. Je vous conseille d'aller vers ce qui est familier et bon.",
    faq_a_shop_basics: "Quand la Liste de Courses est complètement vide – par exemple tout au début – une liste de base pour commencer apparaît : lait, pain, œufs et plus encore. Un toucher sur un article l'ajoute à la liste, et « Tout ajouter » ajoute tout d'un coup. Dès qu'il y a quelque chose sur la liste, elle disparaît.",
    faq_q_shop_basics: "Qu'est-ce que la liste de base dans une Liste de Courses vide ?",
