    shop_win_noon: "Après-midi",
    shop_win_other: "Autre…",
    shop_win_to: "À",
    room_genie_again_no: "Pas maintenant",
    room_genie_again_no_msg: "Alors, c'est le moment d'atteindre les objectifs que vous vous êtes déjà fixés. Quand vous arriverez au prochain – quelque chose vous y attendra ✨",
    room_genie_again_q: "De retour ? ✨ Aimeriez-vous changer autre chose dans votre vie ?",
    room_genie_again_yes: "Oui",
    room_genie_bye: "À bientôt",
    room_genie_rest: "L'esprit de la forêt se repose maintenant – revenez demain ✨",
    faq_a_shop_holidays: "Dans la Liste de Courses, touchez le cadeau : les fêtes de votre pays (celui des Paramètres) apparaissent dans l'ordre, avec leurs dates – calculées automatiquement chaque année. Touchez une fête pour obtenir une liste toute prête de ce qu'on achète pour l'occasion ; tout est sélectionné (sauf ce qui est déjà sur votre liste), décochez ce dont vous n'avez pas besoin et touchez « Ajouter à la liste ». Deux semaines avant une fête, une petite carte apparaît en haut de la liste ; ✕ la masque jusqu'à la fête suivante.",
    faq_q_shop_holidays: "Comment fonctionne « Quoi acheter pour la fête » ?",
    shop_hol_add: "Ajouter à la liste ({n})",
    shop_hol_added: "Ajoutés à la liste : {n}",
    shop_hol_btn: "Quoi acheter pour la fête",
    shop_hol_items_title: "{holiday} – quoi acheter ?",
    shop_hol_not_now: "Pas maintenant",
    faq_a_shop_delivery: "Dans la Liste de Courses, touchez le camion : choisissez ce qu'il y a dans la livraison (tout est sélectionné), quand elle arrive – aujourd'hui, demain ou un autre jour – et à quelle heure (matin, après-midi, soir, ou « Autre… » pour vos propres horaires). Ces articles passent sur une carte « En route » en haut de la liste, avec le jour et les horaires. Le jour venu, « La livraison est arrivée ? » apparaît dans Ma Journée (et la carte affiche « C'est arrivé ? »). Si tout est arrivé, ils vont dans « À racheter ». S'il manque quelque chose, touchez ce qui n'est pas arrivé et cela revient directement sur la liste.",
    faq_a_shop_departments: "La liste se range toute seule par rayons du supermarché – fruits et légumes, pain, crèmerie et œufs, viande et poisson, épicerie, surgelés, boissons, snacks, entretien, hygiène, bébé et animaux – pour que vous parcouriez les allées dans l'ordre. Le rayon est reconnu d'après le nom de l'article. Si un article s'est retrouvé au mauvais endroit, touchez-le et choisissez son rayon, ou « Autre… » pour écrire le vôtre.",
    faq_a_shop_share_qty: "Oui. À côté de chaque article, + en ajoute un (×2, ×3…) et − en retire un. Le bouton de partage en haut de la Liste de Courses envoie toute la liste, joliment triée par rayon, par WhatsApp, par e-mail ou en copie.",
    faq_a_shop_two_buttons: "Les deux veulent dire « acheté ». ✕ sert pour ce que vous achetez une seule fois : l'article quitte la liste (et attend dans l'archive 🗑️ au cas où ce serait une erreur). ↺ sert pour ce que vous achetez encore et encore : l'article quitte la liste et attend dans « À racheter » ; le petit bouton ↺ à côté de la corbeille, en bas de la liste, l'ouvre, et un toucher à cet endroit remet un article sur la liste. Dans « Modifier », à l'intérieur, vous pouvez en retirer un article. Quand vous ajoutez un article, ce que vous avez déjà acheté apparaît en suggestion, et s'il est déjà sur la liste, il passe simplement à ×2 au lieu d'occuper une deuxième ligne.",
    faq_q_shop_delivery: "Comment fonctionne « J'ai commandé une livraison » ?",
    faq_q_shop_departments: "Pourquoi ma liste de courses est-elle divisée en rayons ?",
