    nm_demo_title: "Comment fonctionne un échange",
    faq_a_new_me_challenge_journal: "Quand un défi se termine – grand défi, mini-défi ou défi de la semaine –, la célébration affiche un bouton 📝 Comment c'était ? qui ouvre une page du journal des défis : le ressenti (cinq visages), ce qui a aidé, ce qui a été dur et ce que j'en retiens – rien n'est obligatoire, et tout peut aussi se faire plus tard. Le journal est un diamant dans le sac magique : chaque défi terminé avec sa date et ce qui a été écrit, le plus récent en premier – touchez-en un pour le lire, le modifier ou le partager (seul ce qui est sur la page est partagé). Un défi terminé reçoit aussi une médaille dans les réussites, sous « Défis que j'ai terminés ». Le journal des défis est distinct du journal habituel.",
    faq_q_new_me_challenge_journal: "Qu'est-ce que le journal des défis ?",
