    nm_chj_share_text: "J'ai terminé un défi dans New Me ✨",
    nm_chj_take: "Qu'est-ce que j'en retiens ?",
    nm_chj_title: "Journal des défis",
    nm_chj_write: "Écrire comment ça s'est passé",
    nm_swap_time: "Heure",
    faq_a_ai_reminder_in_text: "Oui – écrivez-le avec la tâche, par exemple « demain à 17:00 récupérer le colis, avec un rappel une heure avant ». Le rappel est enregistré sur la tâche elle-même : une heure avant, une demi-heure avant, la veille, etc., et « rappelle-moi » sans heure signifie 10 minutes avant. Un rappel écrit dans le texte a la priorité sur le champ de rappel de la même fenêtre.",
    faq_q_ai_reminder_in_text: "Puis-je demander un rappel à l'assistant IA dans la même demande ?",
    myday_meals_all_done: "Tous les repas du jour sont cochés 🍽️",
    nm_tour_week_text: "Un petit défi pour la semaine. ✓ chaque jour – et une clé à la fin.",
    books_home_chip: "{title} · p. {page}",
    books_home_of: "sur {total}",
    books_home_off_toast: "Le livre a quitté l'écran d'accueil",
    books_home_on_toast: "Le livre est sur l'écran d'accueil 📖",
    books_home_pin: "Sur l'écran d'accueil",
    books_home_q: "À quelle page en suis-je ?",
    books_home_save: "Enregistrer",
    faq_a_books_home_chip: "Oui. Dans le Coin lecture, sur la carte d'un livre en cours de lecture, touchez 📌 Sur l'écran d'accueil. Un petit bouton avec le livre et la page apparaît sur l'écran d'accueil, sous la salutation : touchez-le, saisissez le nouveau numéro de page et enregistrez, et la progression est suivie (dans le Coin lecture aussi). Toucher 📌 à nouveau le retire. Plusieurs livres peuvent y être en même temps – un bouton pour chacun – et c'est identique sur tous les appareils.",
    faq_a_new_me_week_challenge: "Un petit défi d'une semaine, choisi par vous. Dans le couloir, il y a une grande carte : « Sur quoi aimeriez-vous travailler cette semaine ? » Touchez-la, choisissez un domaine (avec moi-même, avec les autres, apprendre et grandir, calme, petits pas courageux, maison et routine) et un défi, puis décidez quand il commence. Les mêmes défis se trouvent aussi dans l'écran des défis, sous 🌱 Développement personnel. Chaque jour, on coche ✓ sur la carte (un jour libre par semaine), et chaque semaine terminée apporte une nouvelle clé pour le monde secret. « Lire 2 pages par jour » se coche tout seul grâce aux pages notées dans le Coin lecture. Quand la semaine se termine, 📌 Le garder comme tâche quotidienne l'ajoute à Ma Routine à l'heure choisie, avec un ✓ chaque jour. Un seul défi de la semaine à la fois ; les grands défis et les mini-défis continuent en parallèle.",
    faq_a_room_genie: "Sur le porche face à la mer, un toucher sur la lampe d'Aladin fait sortir l'esprit de la forêt – et une conversation commence : quel est votre vœu (qu'aimeriez-vous changer dans votre vie), quel effet cela fera quand il se réalisera, ce qui est difficile sur le chemin, et comment la situation actuelle peut devenir quelque chose de bien. Ensuite, à peu près combien de temps cela prendra, une première petite étape et deux autres, et un « si… alors… » pour les moments difficiles. À la fin, tout le vœu apparaît étape par étape, et il peut devenir un objectif dans Mes Objectifs (les étapes jalonnent alors son chemin, avec une date selon la durée choisie ; tout peut y être modifié) ou être enregistré dans le journal – puis l'esprit dit au revoir. Rien n'est enregistré si aucune des deux options n'est choisie. Dès la deuxième visite, l'esprit demande d'abord si vous aimeriez changer autre chose dans votre vie : oui – la même conversation ; pas maintenant – un rappel d'atteindre les objectifs déjà fixés. L'esprit sort une fois par jour : après l'enregistrement d'un vœu (ou après « Pas maintenant »), il se repose jusqu'au lendemain. Les questions suivent une méthode connue pour transformer un vœu en plan : vœu, résultat, obstacle et plan.",
    faq_q_books_home_chip: "Puis-je voir mon livre et ma page sur l'écran d'accueil ?",
    faq_q_new_me_week_challenge: "Qu'est-ce que le défi de la semaine ?",
    faq_q_room_genie: "Que fait le génie de la lampe ?",
