    room_genie_to_goal: "✨ En faire un objectif dans Mes Objectifs",
    room_genie_turn_ex: "Par exemple : vivre à la maison est difficile – mais dehors ce sera difficile aussi. Alors, qu'est-ce que la maison offre en ce moment et qu'on peut utiliser ?",
    room_genie_turn_q: "Parfois, ce qui est difficile est aussi une chance. Comment utiliser la situation actuelle pour en faire quelque chose de bien ?",
    room_sign_text: "Prendre soin de moi",
    room_game_tag: "En chemin, on s'arrête pour profiter",
    room_drawer_aria: "Petit meuble",
    nm_me_choose: "Choisir",
    nm_me_on_screen: "À l'écran",
    faq_a_new_me_game: "Dans New Me, les boutons du jeu restent toujours au même endroit – dans le couloir, dans la chambre secrète et partout dans la forêt ; seule la peinture du milieu change. En haut : le jour dans le parcours, les clés, la série et l'énergie du jour (la part du programme déjà mangée), et juste en dessous la prochaine mission – le prochain repas à son heure (un toucher l'ouvre, avec ✓ C'est mangé). Sur le côté : toute la journée, défis et mon parcours, et juste à côté le défi de la semaine – ses 7 jours et un ✓ pour aujourd'hui. En bas : le sac magique (tout New Me – carte du monde, mon parcours, liste de courses, réussites, journal des défis, mensurations, photos d'évolution, calendrier mensuel, tableau du jour, rappels, menu en PDF et réglages ; il s'ouvre comme un écran à part). La carte du monde, la première chose dans le sac, montre tous les lieux de la forêt – touchez un lieu pour y aller ; un lieu fermé indique combien de clés il lui faut. Sky est votre personnage sur le sentier dans la forêt : il commence en Sky 1, après quelques défis (4 clés) il grandit et devient Sky 2, et vers la fin (9 clés) Sky 3 – avec une métamorphose qu'on voit en direct. Touchez Sky pour voir toutes les étapes – toute étape déjà atteinte peut être choisie de nouveau, donc une étape précédente peut revenir. Sky flotte : on le fait glisser du doigt ou à la souris, et l'entrée qu'il touche s'ouvre (sur une entrée verrouillée, on voit combien de clés manquent). Sky vous accompagne aussi dans chaque pièce et chaque lieu, et flotte là où vous le laissez : faites-le glisser n'importe où, et faites glisser l'anneau lumineux en dessous pour le faire tourner complètement sur lui-même ; il regarde dans la direction où il avance (sur ordinateur : les flèches le déplacent, Q et E le font tourner). Dans le couloir, le petit 🏠 sous la barre du haut ramène à l'écran d'accueil ; dans chaque pièce et chaque lieu, le bouton du même coin ramène au couloir.",
    faq_q_new_me_game: "Comment fonctionnent les boutons du jeu, la carte du monde et Sky ?",
