    room_magic_song_rec3: "Carillons de la cascade",
    faq_a_new_me_menu_build: "D'abord, le questionnaire demande quels repas vous prenez et à quelle heure (2 repas + une collation, 2 repas + un dîner léger, ou les deux), et s'il y a quelque chose le soir – à manger ou à boire, quoi et à quelle heure. Avec « 2 repas + une collation », les repas sont le déjeuner (11:30) et le dîner (19:00), avec la collation à 16:00. Ensuite, toutes les propositions pour ces repas apparaissent. Choisissez jusqu'à 2 favoris par repas – le menu affiche « ceci ou cela ». Dans certaines propositions (pita et pâte à tartiner, pétales de maïs et lait, quelque chose de léger), vous choisissez jusqu'à 3 choses que vous aimez, chacune avec sa propre portion, et le menu affiche « ceci ou cela ou autre chose » ; les calories s'adaptent à ce que vous avez choisi. Le café et les boissons fonctionnent de la même façon. Chaque choix est équilibré, donc la journée fait exactement 1 300 ou 1 500. Pour changer à tout moment : ⚙️ Réglages → 🍽️ Composez votre menu, ou « Choisissez-en jusqu'à 3 qui vous plaisent » sur la carte du repas.",
    faq_q_new_me_menu_build: "Comment le menu New Me est-il composé ?",
