    faq_a_myday_water_toggle: "Oui. Le verre d'eau dans « Ma Journée » (avec + pour un verre de plus) est affiché par défaut. Pour le masquer, désactivez « Afficher l'eau dans “Ma Journée” » dans Paramètres > Personnalisation et calendrier. Rien n'est supprimé : le Suivi de l'Eau continue de fonctionner, et réactiver l'option fait revenir le verre.",
    faq_q_myday_water_toggle: "Puis-je masquer l'eau dans « Ma Journée » ?",
    myday_water_toggle_label: "Afficher l'eau dans « Ma Journée »",
    faq_a_routine_newme_sync: "Avec New Me, le ⚙️ de Ma Routine a un interrupteur « Synchroniser avec New Me ». Activé (par défaut), les repas du jour de New Me apparaissent dans Ma Journée et dans Ma Routine – à la place des repas de la routine qui ont été masqués. Désactivé, les repas New Me quittent les deux et la routine redevient exactement comme avant. Rien n'est supprimé – le réactiver remet tout et demande quels repas de la routine masquer.",
    faq_q_routine_newme_sync: "Comment activer ou désactiver la synchronisation de New Me avec Ma Routine et Ma Journée ?",
