    theme_name_watercolor_wash: "Aquarelle",
    faq_a_food_list_languages: "La liste d'aliments intégrée a commencé avec des plats israéliens et leurs noms en hébreu. Dans les autres langues, chaque aliment s'affiche avec son nom anglais, et la recherche trouve tous les noms anglais qu'elle connaît (par exemple 'broth' trouve Clear soup) ; les aliments qui n'ont qu'un nom en hébreu n'y figurent pas. Tout ce qui n'est pas dans la liste peut simplement être écrit avec vos propres mots – l'estimation par IA fonctionne dans toutes les langues.",
    faq_q_food_list_languages: "Pourquoi la liste des aliments affiche-t-elle des noms en anglais, et moins d'aliments, dans ma langue ?",
    settings_copyright_line: "© 2026 tous droits réservés. application développée par eden zabari.",
    workout_ready_replace_btn: "Remplacer",
    faq_a_sport_workout_ai: "Dans Mes entraînements → ⋯ → Programme avec l'IA (et, quand le tableau est vide, aussi sur la tuile à côté des programmes prêts). Répondez en quelques touches – combien de fois par semaine, quand, lieu, niveau et objectif, presque tous avec « Autre » – et ajoutez si vous voulez une ligne libre, comme un genou sensible ou courir 5 km d'ici l'été. L'IA crée une semaine complète : types d'entraînement, jours, heures, durée, intensité, exercices et jours de repos. Rien n'est enregistré avant un aperçu : « Le mettre dans mon tableau » (à la place du tableau ou en plus), « Une autre proposition » (jusqu'à 3 fois) ou « Modifier les réponses ». Le programme est modéré exprès, et si vous mentionnez une douleur ou une blessure, vous recevez des options douces et le conseil de consulter un professionnel. Il utilise le même quota d'IA que l'agenda et la routine : 5 fois gratuitement, et 60 par mois avec Premium.",
    faq_q_sport_workout_ai: "Comment créer un programme d'entraînement avec l'IA ?",
