    workout_ai_other: "Autre",
    workout_ai_replace: "À la place de mon tableau",
    workout_ai_title: "Programme d'entraînement avec l'IA",
    workout_ai_when_evening: "Soir",
    workout_ai_when_label: "Quand",
    workout_ai_when_morning: "Matin",
    workout_ai_when_noon: "Midi",
    workout_ai_when_ph: "ex. après le travail, ou 17:30",
    workout_ai_working: "Votre programme arrive…",
    faq_a_sport_workout_jar: "Chaque type d'entraînement a sa propre étoile de couleur : course rose, marche verte, natation bleue, etc. Chaque entraînement enregistré cette semaine, depuis le tableau ou à part, fait tomber son étoile dans le bocal en haut de Mes entraînements, et le bocal se remplit jusqu'à votre objectif hebdomadaire (touchez-le pour changer l'objectif). Une fois l'objectif atteint, le bocal brille. Le petit bocal à côté compte combien de semaines d'affilée vous l'avez rempli.",
    faq_q_sport_workout_jar: "Que sont les étoiles de couleur et le bocal dans Mes entraînements ?",
    faq_a_sport_workout_gcal: "Oui – dans ⋯ → Google Agenda (une fois Google Agenda connecté dans les Réglages). Chaque entraînement avec une heure devient un événement qui se répète chaque semaine à ses jours, et les changements dans l'app le mettent à jour. Les rappels viennent uniquement de l'app, donc Google n'en ajoute pas, et les entraînements n'apparaissent jamais en double dans l'app. Un nouvel appui retire de Google Agenda uniquement les entraînements.",
    faq_q_sport_workout_gcal: "Mes entraînements peuvent-ils apparaître dans Google Agenda ?",
    workout_gcal_btn: "Google Agenda",
    workout_gcal_error: "Google Agenda n'a pas pu être mis à jour – nouvel essai au prochain changement",
    workout_gcal_not_connected: "Connectez d'abord Google Agenda dans les Réglages",
    workout_gcal_off_toast: "Les entraînements ont été retirés de Google Agenda",
    workout_gcal_on_toast: "Vos entraînements sont dans Google Agenda",
    faq_a_sport_workout_reminder: "Oui – dans un entraînement, Rappel : 10 minutes, 30 minutes ou une heure avant, ou un délai personnalisé (l'entraînement doit avoir une heure). Il sonne comme vos autres rappels, une seule fois et à un seul endroit : dans l'app si elle est ouverte, sinon sur votre téléphone. « Fait » enregistre l'entraînement dans l'historique, et « Pas encore » le rappelle dans 5 minutes.",
    faq_q_sport_workout_reminder: "Puis-je avoir un rappel avant un entraînement ?",
    workout_reminder_30min: "30 minutes avant",
    workout_reminder_label: "Rappel",
    workout_reminder_need_time: "Ajoutez une heure pour recevoir un rappel",
    faq_a_sport_workout_share: "Dans ⋯ → Partager, la semaine devient une image effet verre aux couleurs de votre thème, avec un lien discret vers l'app (sur téléphone, elle va directement au menu de partage ; sur ordinateur, l'image est enregistrée). ⋯ → PDF à imprimer ouvre une page nette de toute la semaine, avec une case à cocher à côté de chaque entraînement et exercice – choisissez « Enregistrer en PDF » ou imprimez-la. Le programme figure aussi dans le rapport de données des Réglages, partie Sport.",
    faq_q_sport_workout_share: "Comment partager ou imprimer ma semaine d'entraînement ?",
    share_image_saved: "L'image est enregistrée – vous pouvez la joindre",
    share_save_image: "Enregistrer l'image",
    workout_pdf_btn: "PDF à imprimer",
    workout_share_btn: "Partager",
    faq_a_sport_workout_board: "Dans ⋯ → Tableau de la semaine, chaque jour est une colonne : faites glisser un entraînement vers un autre jour (sur téléphone, appuyez longuement d'abord). Dans un entraînement, « Aussi dans Ma Routine » l'ajoute à votre routine à son heure et ses jours, et les changements restent synchronisés dans les deux sens ; depuis un élément de Ma Routine, « Ajouter à mes entraînements » fait l'inverse. Un ✓ d'un côté compte des deux, et dans Ma Journée il n'apparaît qu'une fois : dans la pastille à côté de l'eau.",
    faq_q_sport_workout_board: "Comment déplacer un entraînement à un autre jour et le relier à Ma Routine ?",
    routine_in_workouts_btn: "Ouvrir dans mes entraînements",
