    workout_moved: "Déplacé à {day}",
    workout_routine_need_time: "Ajoutez une heure pour le mettre dans Ma Routine",
    workout_routine_toggle: "Aussi dans Ma Routine",
    workout_view_board: "Tableau de la semaine",
    workout_view_timeline: "Frise",
    faq_a_sport_workout_plan: "Dans Suivi des Entraînements, sous « Mes entraînements » : + Entraînement – type, jours, heure, durée, intensité et lieu (aussi « Autre »). Les séances de renforcement, de fonctionnel et de natation peuvent contenir une liste d'exercices, et Repos marque un jour de repos. Vous pouvez aussi partir d'un programme prêt. L'entraînement du jour s'affiche en grand, avec toute la semaine dessous ; ✓ l'enregistre dans l'historique avec son intensité. Dans ⋯, vous fixez un objectif hebdomadaire (entraînements ou minutes) : chaque entraînement fait tomber son étoile dans le bocal.",
    faq_a_sport_workout_today: "Dans Ma Journée, à côté de l'eau, une petite pastille montre l'entraînement du jour – un toucher ouvre les détails, ✓ et ▶. ▶ lance un chrono qui continue dans la pastille de l'écran d'accueil, et « Terminer » enregistre l'entraînement avec le temps réel. Si le défi « Deux semaines en mouvement » de New Me est en cours, un entraînement enregistré y compte tout seul.",
