    faq_a_new_me_magic_themes: "Cinq thèmes scintillants inclus avec New Me : Forêt enchantée, Poussière d'étoiles, Fée des roses, Aurore magique et Crépuscule doré. Choisissez-en un dans New Me (⚙️ Réglages > Couleurs) ou dans Paramètres > Apparence et affichage, et un pinceau à paillettes peint l'écran avec. Un thème magique ajoute des paillettes dans toute l'appli et à chaque toucher. Vous pouvez revenir à n'importe quel autre thème à tout moment.",
