    apptour_focus_text: "Tout s'efface sauf la seule chose du moment, avec un grand ✓. Ensuite, la suivante apparaît.",
    apptour_m_presets_text: "Vos repas enregistrés au même endroit : recherche, récemment utilisés, par moment de la journée – et ＋ en ajoute un à aujourd'hui.",
    apptour_night_text: "🌙 assombrit toute l'appli ; ☀️ ramène le jour.",
    apptour_noteline_text: "Écrivez et touchez ➤ : c'est enregistré dans vos notes. 📝 au début passe à 🛒 les courses ou à 🍎 un repas enregistré.",
    apptour_search_text: "Notes, courses, calendrier, recettes, cahiers, objectifs, tableaux et livres : une seule recherche trouve tout.",
    faq_a_new_me_ai_menu: "Avant le menu, le questionnaire demande quels repas vous prenez et à quelle heure (2 repas + une collation, 2 repas + un dîner léger, ou les deux), si vous prenez quelque chose de léger le soir et à quelle heure, ce que vous ne mangez pas et comment vous buvez votre café ou votre thé. L'IA crée ensuite 3 propositions pour chaque repas – chacune à la taille de sa part de la journée, pour que la journée fasse toujours exactement 1 300 ou 1 500 – ainsi que des idées de boissons, enregistrées comme vos boissons habituelles. Choisissez jusqu'à 2 favoris par repas ; les propositions du menu d'origine sont juste en dessous, et dans 🔄 Remplacer elles viennent après votre menu personnel. 🔄 Autres propositions en crée une nouvelle série (3 fois par questionnaire). Pour changer vos réponses ou créer un nouveau menu à tout moment : ⚙️ Réglages → ✨ Menu personnel (IA).",
    faq_q_new_me_ai_menu: "Comment fonctionne le menu personnel de New Me ?",
    nm_ai_menu_building: "Création d'un menu selon vos repas et vos horaires…",
    nm_ai_menu_drinks: "Boissons pour vous",
    nm_ai_menu_error: "Le menu personnel n'a pas pu être créé pour l'instant – voici le menu d'origine. Vous pouvez réessayer, ou plus tard depuis ⚙️ Réglages.",
