    apptour_s_gcal_inside_text: "Connectez Google Calendar une seule fois : événements et tâches restent synchronisés dans les deux sens.",
    apptour_s_menu_text: "Tout ce que vous pouvez régler se trouve ici, en cinq groupes. Ouvrons-les 👇",
    apptour_skip_part: "Passer cette partie",
    apptour_start: "Commencer la visite",
    nm_sales_premium: "Inclut tout Premium",
    nm_unlock_premium: "Et tout Premium est débloqué aussi.",
    settings_sub_status_newme: "Premium est inclus dans ton New Me.",
    room_back_to_shelf: "Vers l'étagère",
    faq_a_new_me_day_total: "Chaque journée correspond exactement au programme : les repas, environ 150 calories pour le café et les boissons dans la journée, et ce qui a été choisi pour le soir – un petit quelque chose à manger ou quelque chose à boire. Pour le soir, choisissez-en jusqu'à 3 qui vous plaisent (par exemple une banane, un yaourt ou 2 carrés de chocolat noir ; ou une tisane, un thé avec un peu de lait ou du lait chaud), et leurs calories sont prises sur les repas. Chaque choix s'équilibre tout seul : une option plus petite ou plus grande, un repas retiré, le petit déjeuner léger et le petit repas qui l'accompagne, ou le soir – la différence est ajoutée aux repas ou retirée, à chacun selon sa taille, et sous chaque repas il est indiqué combien (+ ou −) et quoi ajouter ou enlever. Un repas déjà coché reste tel qu'il a été enregistré. Dans le questionnaire, chaque repas montre son ajustement, et un petit encadré montre repas, boissons, soir et total. Envie d'autre chose ce jour-là ? Gardez le total au même nombre de calories ou moins.",
    faq_q_new_me_day_total: "Comment une journée New Me fait-elle exactement 1 300 / 1 500, et où comptent les boissons ?",
