    nm_less_line: "{n} calories dans ce repas, pour que la journée fasse {plan} – par exemple {ideas}",
    nm_less_line_late: "{n} calories dans ce repas, pour un petit quelque chose à {time} – par exemple {ideas}",
    nm_swap_balanced: "{n} calories réparties entre les repas, pour que la journée fasse {plan}",
    books_quotes_chip: "Citations",
    faq_a_book_quotes: "Sur l'étagère de la chambre secrète (Citations), ou avec la petite pastille 💬 Citations du Coin lecture – c'est la même liste. Touchez « + Citation », écrivez la phrase et choisissez le livre dans votre Coin lecture, ou tapez un autre titre avec « ✏️ Autre » ; l'auteur est facultatif. ✏️ modifie une citation et 🗑️ la supprime. Les citations sont des marque-pages qu'on fait défiler : 🎨 en haut passe aux photos ou à un mur de cartes.",
    faq_a_room_wish_jar: "Sur l'étagère de la chambre secrète, il y a un bocal en verre pour les rêves. Touchez le petit bocal de l'étagère du haut (ou Étagère > Le bocal à vœux) et écrivez à quoi vous aimeriez que votre vie ressemble – aussi fou que vous voulez, sans bien ni mal. Chaque vœu est plié en papier et tombe dans le bocal. « Tirer un papier » en ouvre un au hasard, et chaque papier peut aussi être ouvert seul. Dès la deuxième fois que vous ouvrez le même vœu, vous pouvez en faire un objectif et le découper en petites étapes. Une fois par semaine, un papier avec l'un de vos vœux apparaît en douceur – sans pression, juste un rappel de votre direction.",
    faq_q_book_quotes: "Où garder les citations de livres que j'ai aimés ?",
    faq_q_room_wish_jar: "Qu'est-ce que le bocal à vœux de la chambre secrète ?",
