    room_wish_written: "Écrit le {date}",
    faq_a_saved_meals_page: "Les repas enregistrés ont leur propre page : Nutrition et Métriques > ⭐ Repas enregistrés (ou ⭐ dans le menu). La recherche en haut trouve un repas par son nom ou un ingrédient, « Utilisés récemment » montre ce que vous avez ajouté dernièrement, et les onglets (Petit-déjeuner, Déjeuner, Dîner, Soupes…) montrent chaque moment de la journée. « + Aujourd'hui » ajoute un repas au Suivi Quotidien des Repas d'aujourd'hui, dans la prochaine case libre. Touchez un repas pour le modifier ou le supprimer, et ＋ en haut en ajoute un nouveau.",
