    presets_tab_snack: "En-cas",
    presets_tab_soup: "Soupes",
    presets_tab_sweet: "Sucreries",
    faq_a_notes_sticky_look: "Les notes forment une courte liste de cartes en verre : 🎨 en haut de Notes change l'apparence de toutes les Notes (la liste, les boutons des jours en haut et la fenêtre où l'on écrit une note) : verre, liste épurée, fiches ou masking tape. Une note qu'on fait glisser garde exactement sa propre apparence et sa couleur. Touchez le texte d'une note pour l'ouvrir : vous pouvez alors la modifier, changer ses couleurs et voir quand elle a été écrite pour la dernière fois. Touchez ○ quand c'est fait, et × la met aux archives (🗑️ en bas de la liste la récupère). Faites-la glisser par ⠿ pour changer l'ordre, sous « Plus tard » ou sur un jour en haut. ! marque une note comme urgente – elle remonte doucement vers les premières lignes avec une petite étiquette « Urgent » ; un autre toucher l'enlève.",
    faq_q_notes_sticky_look: "Comment ouvrir, modifier ou retirer une note ?",
    note_to_archive_btn: "Mettre aux archives",
    faq_a_routine_clash: "S'il y a déjà un élément à cette heure les mêmes jours, deux choix s'offrent à vous : « Remplacer » – le nouvel élément prend cette heure et vous choisissez une heure pour celui qui y était (quand vous modifiez un élément existant, son ancienne heure est proposée, donc les deux s'échangent simplement), ou « Les deux » – ils restent tous les deux à la même heure, l'un sous l'autre. Si les jours sont différents (par exemple l'un du dimanche au jeudi et l'autre le vendredi), aucune question n'est posée.",
    faq_q_routine_clash: "Que se passe-t-il si je mets un élément de la routine à une heure déjà prise ?",
    routine_clash_both: "✌️ Les deux – tous les deux à {time}",
    routine_clash_move_btn: "Déplacer et enregistrer",
    routine_clash_move_to: "À quelle heure déplacer « {title} » ?",
    routine_clash_replace: "🔄 Remplacer – et déplacer « {title} » à une autre heure",
    routine_clash_title: "À {time}, il y a déjà : {title}",
    faq_a_new_me_coffee: "Sous le menu du jour, un petit résumé indique combien de calories font tous les repas de la journée et ce qu'il reste pour le café et les boissons, avec des boutons pour le café et les boissons choisis – un toucher l'ajoute aux Boissons. Dans « Choisissez-en jusqu'à 3 qui vous plaisent », sous les boutons (et dans le questionnaire), choisissez ce qui s'affiche : eau / eau gazeuse, tisane, un soda light, noir / americano (~5), thé avec un peu de lait (~25), café allongé à l'eau avec jusqu'à 100 ml de lait ou de boisson végétale (~50), chocolat chaud léger, lait chaud ou café classique / latte (~120).",
