    nm_late_room_line: "Un petit quelque chose avant de dormir · il reste ~{n} kcal aujourd'hui",
    faq_a_recipe_examples: "Sous vos recettes, il y a des exemples de recettes : petits-déjeuners, salades, soupes, plats, accompagnements, en-cas, desserts et plats végans, chacun avec le temps de préparation, les calories par portion et le poids d'une portion en grammes. Touchez une recette pour l'ouvrir ; « Enregistrer dans Mes Recettes » crée votre propre copie, que vous pouvez modifier. Les étiquettes de catégorie filtrent, et toucher la même étiquette une seconde fois réaffiche tout.",
    faq_a_recipe_grams: "Dans une recette, à côté des calories, il est écrit « 1 portion ≈ X g ». Pour vos propres recettes, remplissez « Grammes par portion » (et le temps de préparation si vous voulez) dans le formulaire de la recette : les deux sont facultatifs, et le temps s'affiche sur la bande de couleur de la recette.",
    faq_q_recipe_examples: "Que sont les exemples de recettes dans Mes Recettes ?",
    faq_q_recipe_grams: "Comment voir combien de grammes fait une portion ?",
    recipe_category_vegan: "Végan",
    recipe_grams_placeholder: "Grammes par portion",
    recipe_meta_grams: "1 portion ≈ {n} g",
    recipe_meta_grams_short: "{n} g",
    recipe_meta_minutes: "{n} min",
    recipe_minutes_placeholder: "Temps de préparation (minutes)",
    recipe_save_example_btn: "Enregistrer dans Mes Recettes",
    recipe_saved_example: "✓ Enregistrée dans Mes Recettes",
    recipe_saved_example_toast: "Enregistrée dans Mes Recettes : vous pouvez la modifier là-bas",
    recipes_examples_title: "Exemples de recettes",
    faq_a_recipe_scan_multi: "Oui. Dans « Ajouter une Recette », touchez 📷 et choisissez une photo ou plusieurs (jusqu'à 6 ; un PDF fonctionne aussi). Chacune apparaît dans une courte liste où vous indiquez ce qu'elle contient : Tout, Ingrédients ou Préparation, et « ➕ Une autre photo » en ajoute d'autres. Touchez ensuite « ✨ Scanner la recette » : l'IA rassemble tout en une seule recette, dans l'ordre et sans lignes en double, et cela compte comme un seul scan. Plusieurs photos choisies depuis 📷 Photo dans l'assistant IA s'ouvrent aussi ici.",
    faq_q_recipe_scan_multi: "Puis-je scanner une recette à partir de plusieurs photos, par exemple les ingrédients et les étapes séparément, ou deux pages ?",
    recipe_scan_add_more: "➕ Une autre photo",
    recipe_scan_part_all: "Tout",
    recipe_scan_part_ingredients: "Ingrédients",
    recipe_scan_part_steps: "Préparation",
    recipe_scan_remove_photo: "Retirer la photo",
    recipe_scan_run_btn: "✨ Scanner la recette",
    recipe_scan_too_many: "Jusqu'à {n} photos par recette",
    faq_a_note_written_at: "Touchez le texte de la note pour l'ouvrir. À l'intérieur, sous le texte, s'affiche le moment où elle a été écrite pour la dernière fois, avec la date et l'heure exactes. Seule une modification du texte la met à jour : l'archiver puis la restaurer, la cocher ✓, les couleurs ou la déplacer ne la changent pas.",
    faq_q_note_written_at: "Comment voir quand j'ai écrit une note ?",
    note_written_at: "Écrite pour la dernière fois : {date}",
    faq_a_new_me_month: "Dans le sac magique → Calendrier mensuel : chaque jour est coloré selon le nombre de repas cochés, les flèches ‹ › passent d'un mois à l'autre, et sous le calendrier s'affiche la moyenne de calories par jour du mois. Un appui sur un jour montre combien de repas ont été cochés et combien de calories ont été mangées ce jour-là.",
    faq_q_new_me_month: "Où revoir le mois passé et ma moyenne de calories dans New Me ?",
    nm_month_avg: "Moyenne du mois : {kcal} calories par jour · jours notés : {n}",
    nm_month_day_empty: "Rien n'a été noté ce jour-là.",
    nm_month_day_line: "Repas cochés : {checks} · calories : {kcal}",
    nm_extra_line_small: "{n} calories pour ce repas, venant du petit déjeuner léger – par exemple {ideas}",
    faq_a_new_me_small_breakfast: "Un petit déjeuner léger (environ 170 kcal) : une pita d'épeautre (jusqu'à 100 kcal) avec une pâte à tartiner ou du fromage, plus un légume – choisissez-en jusqu'à 3 qui vous plaisent, par exemple 1 c. à café de pâte à tartiner au chocolat, 1 c. à café de beurre de cacahuète ou une tranche de fromage à pâte pressée (jusqu'à 22 %). Comme il est petit, « Et un petit repas en plus » l'accompagne à une autre heure (une heure et demie plus tard, par exemple 11:30 → 13:00 – n'importe quelle autre heure peut être choisie) : une autre pita et pâte à tartiner, un yaourt protéiné et un fruit, des galettes de riz et du fromage, des céréales et du lait ou une demi-pita et des œufs – jusqu'à environ 200 kcal, avec son propre ✓. Ce qui reste encore est réparti entre les autres repas, et chaque repas indique combien il a reçu, donc le total de la journée reste celui du programme. Choisissez-le dans le questionnaire, ou passez-y pour aujourd'hui seulement avec 🔄 – par exemple quand le petit déjeuner est tardif.",
    faq_q_new_me_small_breakfast: "Qu'est-ce que le « petit déjeuner léger » du menu New Me ?",
    home_note_meal_ai: "✨ Calculer avec l'IA",
    home_note_meal_none: "Aucun repas enregistré de ce nom",
    myday_earlier: "Plus tôt",
    nm_ing_spelt_pita: "Pitas d'épeautre",
    nm_ing_spread: "Pâte à tartiner (chocolat / beurre de cacahuète / tahini cru)",
    weather_now: "Dehors maintenant : {sky}",
    weather_sky_clear: "Dégagé",
    weather_sky_clouds: "Nuageux",
    weather_sky_fog: "Brouillard",
    weather_sky_partly: "Partiellement nuageux",
    weather_sky_rain: "Pluie",
    weather_sky_snow: "Neige",
    weather_sky_storm: "Orage",
    faq_a_ai_icon: "Oui, dans Paramètres > Apparence et affichage. La bulle douce est l'icône par défaut, et avec Premium vous pouvez aussi choisir un cerveau flottant ou un robot.",
    faq_a_new_me_favorites: "Oui. Dans le questionnaire (et en le refaisant depuis les réglages), vous pouvez choisir jusqu'à 2 options par repas. La première s'affiche dans le menu, avec une ligne « ou » en dessous pour la seconde : un appui dessus passe à celle-ci pour aujourd'hui seulement. Et si le petit-déjeuner n'a pas été pris à temps, « ⏰ Plus tard » le reporte à plus tard dans la journée, sans changer les calories.",
    faq_a_theme_mode: "Certains thèmes spéciaux sont plus beaux en sombre – Aquarelle, Aurore boréale, Barbie et les deux thèmes Paillettes – : en choisir un fait passer l'appli en mode sombre, et choisir n'importe quel autre thème (la fusée aussi) la fait passer en clair. Noir et Gris foncé restent sombres. Vous pouvez toujours changer ensuite avec 🌙 dans le menu ou avec Mode Clair dans les paramètres.",
    faq_a_water_month: "Dans le suivi de l'eau. Chaque entrée du journal du jour affiche l'heure à laquelle elle a été ajoutée, et « Tableau mensuel » ouvre tout le mois : chaque jour indique combien de litres ont été bus (✓ quand l'objectif quotidien est atteint), et un appui sur un jour affiche ses entrées avec leurs heures.",
    faq_q_ai_icon: "Puis-je changer l'icône de l'assistant IA ?",
    faq_q_new_me_favorites: "Puis-je choisir deux options préférées pour un repas dans New Me ?",
    faq_q_theme_mode: "Pourquoi l'appli est-elle passée en sombre (ou en clair) quand j'ai choisi un thème ?",
    faq_q_water_month: "Où voir combien d'eau j'ai bu chaque jour ?",
