    nm_times_same_kcal: "Quel que soit le choix, les calories de la journée restent les mêmes : ce qui est retiré est réparti entre les autres repas.",
    dev_sim_panel_title: "PM – rien que pour vous",
    faq_a_new_me_weight_optional: "Non. Le poids actuel comme le poids cible du questionnaire sont facultatifs. Si une pesée est ajoutée plus tard (⚖️ Poids dans « Mon parcours » de New Me, ou dans le suivi du poids), la progression est calculée à partir de la première.",
    faq_q_new_me_weight_optional: "Faut-il indiquer son poids dans New Me ?",
    nm_unlock_desc: "Le menu, les défis et le parcours sont prêts – pas à pas, ensemble.",
    nm_unlock_title: "New Me est débloqué !",
    room_reveal_star: "Une nouvelle étoile s'est allumée dans le télescope sur le toit ✨",
    faq_a_room_records: "Le tourne-disque est dans la pièce dès le début, sur la souche d'arbre près du fauteuil. Ses disques ouvrent sur YouTube les clips officiels de grands tubes de ces dernières années, et en dessous il y a cinq airs calmes qui jouent ici même dans la pièce – le disque tourne pendant qu'ils jouent, et « ⏹ Arrêter » coupe la musique.",
    faq_a_room_roof_gifts: "Ils arrivent avec la 8e clé. Toucher le télescope permet de regarder à travers : le ciel nocturne de près – faites glisser (ou utilisez les flèches) pour regarder autour de vous – et vos défis terminés y forment une constellation, une étoile par défi ; toucher une étoile montre lequel c'était. Toucher le petit coffre l'ouvre – pour l'instant il est vide – et un autre toucher le referme.",
    faq_q_room_records: "Qu'y a-t-il sur le tourne-disque de la chambre secrète ?",
    faq_q_room_roof_gifts: "Que sont le télescope et le coffre sur le toit ?",
    room_chest_letter: "Un petit mot pour vous",
    room_chest_letter_1: "Chaque petit pas du chemin était réel – et chacun compte.",
    room_chest_letter_2: "Prendre soin de soi fait partie du chemin, ce n'est pas une pause.",
    room_chest_letter_3: "Il y a des jours plus légers et d'autres plus lourds. Être là pour les deux, c'est la vraie force.",
    room_chest_letter_4: "Le repos est permis. Se reposer, c'est aussi avancer.",
    room_chest_letter_5: "Les changements qui durent sont les plus discrets – ils se construisent jour après jour.",
    room_chest_letter_6: "Aujourd'hui est un bon jour pour ressentir de la fierté – même un tout petit peu.",
    room_chest_letter_7: "Pas besoin de tout faire. Juste la prochaine petite chose.",
    room_chest_letter_8: "Quoi qu'il se soit passé hier, aujourd'hui est un nouveau départ.",
    room_chest_locked: "3 jours d'affilée avec ✓ ouvrent le coffre · {n}/3",
