    room_vinyl_here: "🎻 Des airs calmes, ici dans la pièce",
    room_vinyl_yt: "🎬 Les clips officiels sur YouTube",
    dev_sim_buy: "Comme si c'était acheté – voir comment tout s'ouvre",
    dev_sim_lock: "Verrouiller – voir comme avant l'achat",
    dev_sim_locked_toast: "🔒 Verrouillé – voici l'aspect avant l'achat",
    faq_a_new_me_preview: "Oui. La page New Me s'ouvre sur une courte vidéo de ce qui se passe à l'intérieur : le questionnaire, les lampes du couloir, le sac magique, les défis et les clés. En dessous se trouvent tout ce qui est inclus, un aperçu d'une journée et de courtes réponses.",
    faq_q_new_me_preview: "Peut-on voir New Me avant de l'acheter ?",
    nm_trailer_c1: "Un court questionnaire – et votre menu est prêt",
    nm_trailer_c2: "Chaque repas est une lampe dans votre couloir",
    nm_trailer_c3: "Dans le sac magique : le menu du jour, l'eau et les courses",
    nm_trailer_c4: "Un petit défi terminé – une clé en plus",
    nm_trailer_c5: "Et derrière chaque porte – quelque chose rien que pour vous",
    nm_trailer_end: "On commence aujourd'hui, pas à pas",
    nm_trailer_label: "🎬 Une courte vidéo : ce qui se passe dans New Me",
    nm_trailer_pause: "Mettre la vidéo en pause",
    nm_trailer_play: "Lire la vidéo",
    nm_trailer_replay: "Revoir",
    ai_chat_food_edit: "✏️ Corriger calories / protéines",
    ai_chat_food_invalid: "Les calories doivent être un nombre supérieur à 0",
    ai_chat_food_updated: "Mis à jour :",
    faq_a_ai_chat_food_fix: "Oui. Sous la réponse dans la conversation, touchez ✏️ Corriger calories / protéines, modifiez les chiffres et touchez Enregistrer. Seul ce qui vient d'être ajouté change – même si cela a rejoint une collation déjà présente. L'IA peut se tromper : mieux vaut vérifier.",
    faq_a_new_me_home_btn: "Avec New Me, un petit 💎 à côté du mode concentration, en haut de l'écran d'accueil, ouvre le menu du jour. Les repas du jour apparaissent aussi dans Ma Journée, chacun avec un ✓.",
    faq_a_routine_item_days: "Oui. Touchez l'élément dans Ma Routine et choisissez ses jours sous 📅 Jours – par exemple seulement du lundi au vendredi. Les autres jours, il n'apparaît pas dans Ma Journée et n'a pas de ✓ ; dans Ma Routine il reste, plus pâle, avec ses jours à côté. La carte qui pose une question sur un élément après 3 jours sans ✓ ne compte que les jours de cet élément.",
    faq_q_ai_chat_food_fix: "Peut-on corriger les calories ou les protéines après que l'assistant a noté un repas ?",
    faq_q_new_me_home_btn: "Où est New Me sur l'écran d'accueil ?",
    faq_q_routine_item_days: "Un élément de Ma Routine peut-il n'avoir lieu que certains jours ?",
    routine_item_days_label: "📅 Jours",
    home_note_meal_ph: "Chercher un repas enregistré…",
    menu_quick_search: "Recherche rapide",
    nm_times_hint: "Astuce : vous pouvez indiquer l'heure la plus tardive à laquelle vous prenez chaque repas – par exemple 9 h si vous mangez souvent vers 8 h.",
    room_game_marquee: "En chemin, on s'arrête pour profiter",
    room_sand_erase_aria: "Frotter pour effacer",
    faq_a_home_note_line: "Écrivez dans la ligne au milieu de l'écran d'accueil et touchez ➤ (ou Entrée) : c'est enregistré dans Notes. Touchez 📝 au début de la ligne et il devient 🛒 : ce que vous écrivez va alors dans la Liste de Courses. Touchez encore une fois pour 🍎 : tapez quelques lettres, vos repas enregistrés correspondants apparaissent, et un toucher en note un dans les repas du jour. Avec 🎤, vous pouvez simplement le dire.",
    faq_a_night_mode: "Ouvrez le menu ☰ et touchez 🌙 en haut : toute l'app passe en sombre. ☀️ au même endroit ramène le jour. C'est aussi dans les Paramètres, sous Mode Clair.",
    faq_q_home_note_line: "Comment écrire une note rapide depuis l'écran d'accueil ?",
    faq_q_night_mode: "Comment passer en mode nuit ?",
    menu_day_mode: "Mode jour",
    menu_night_mode: "Mode nuit",
    faq_a_secret_room_yoga: "Au bout du sentier dans la forêt, il y a un portail lumineux et, derrière, près d'une cascade, les créatures de la forêt – Lumi, Puffi, Nixie et Sparklet – sont assises en demi-cercle sur leurs tapis, et Flora, la professeure de yoga, est assise face à elles sur l'unique tapis posé sur la pierre. Touchez Flora : elle ouvre les yeux, tout se rapproche, et la conversation commence doucement, avec le temps de lire – Flora demande comment tout le monde va, chaque créature répond sous son propre nom (avec un petit dessin de celle qui parle à côté de chaque ligne), puis elle vous demande comment vous vous sentez avec vos proches. La conversation continue selon vos réponses – des gens bien, quelqu'un de difficile ou un peu de solitude. Chaque chemin se termine par une petite mission (elle peut aller directement dans Ma Journée ; quand la mission consiste à écrire quelque chose, il y a un endroit pour l'écrire, et c'est enregistré dans le journal magique) et une posture avec trois respirations ensemble. ↩ revient d'un pas et ✦ lance une nouvelle conversation. La clé suivante ouvre la cascade : s'asseoir sur la pierre fait tout disparaître, il ne reste que le bruit de l'eau. Quand on se penche sur le bassin, une question monte de l'eau – que ferait votre vrai moi aujourd'hui ? – et la réponse devient une petite tâche dans Ma Journée. C'est un moment doux, pas un substitut à une discussion avec un professionnel.",
    faq_q_secret_room_yoga: "Que se passe-t-il au yoga dans la forêt ?",
    room_back_to_forest: "Retour au sentier",
    room_back_to_yoga: "Retour au yoga",
    room_item_waterfall: "La cascade",
    room_waterfall_pool_aria: "Toucher l'eau",
    room_waterfall_rock_aria: "S'asseoir sur le rocher",
    room_yoga_guide_aria: "Parler avec Flora",
    yg_g_alone: "Merci d'avoir partagé. Ça arrive à tout le monde, parfois.",
    yg_g_alone_q: "Qu'est-ce qui ferait du bien, même juste un peu ?",
    yg_g_critic: "Une critique peut piquer longtemps. Elle parle d'un moment – pas de toute la personne.",
    yg_g_end: "Merci pour ce moment dans le cercle. Vous pouvez revenir quand vous voulez.",
    yg_g_gate: "On a le droit de poser une limite. Une limite n'est pas un mur – c'est une porte.",
    yg_g_good: "Comme c'est beau 💛 Qui vous a fait du bien cette semaine ?",
    yg_g_good_msg: "Les gens bien méritent qu'on le leur dise. Un petit merci peut illuminer toute leur journée.",
    yg_g_hard: "Merci de l'avoir dit. Qu'est-ce qui pèse le plus ?",
    yg_g_listen: "Quand personne n'écoute, c'est fatigant. Votre voix compte, même quand elle est douce.",
    yg_g_new: "Les nouvelles rencontres commencent par un petit bonjour. Un cours, une balade, un groupe – un pas.",
    yg_g_old: "Quelqu'un qui vous connaît déjà, c'est un endroit chaleureux. Un petit message suffit.",
    yg_g_start: "Et maintenant, à vous 🌿 Comment vous sentez-vous avec vos proches ces derniers temps ?",
    yg_g_used: "Quand on donne sans rien recevoir, quelque chose en nous se fatigue. C'est bien de le remarquer.",
