    yg_o_partner: "Mon ou ma partenaire",
    yg_o_used: "L'impression qu'on profite de moi",
    yg_p1_alone: "Nous sommes là 💛",
    yg_p1_good: "Ça fait plaisir à entendre ! Ça m'a réchauffé le cœur.",
    yg_p1_start: "Ma semaine était chargée, mais une bonne amie m'a appelée pile au bon moment.",
    yg_p2_hard: "Moi aussi, j'ai vécu ça. Le dire à voix haute m'a déjà aidé.",
    yg_p2_start: "Moi aussi, ça m'aide d'écouter tout le monde.",
