    yg_pose_heart: "Maintenant le cœur ouvert 💗 Épaules en arrière, poitrine large. Trois respirations ensemble.",
    yg_pose_tree: "Maintenant la posture de l'arbre 🌳 Debout et stable, un pied contre l'autre jambe, les mains en l'air. Trois respirations ensemble.",
    yg_task_good: "Envoyer aujourd'hui un petit message de remerciement",
    yg_task_hard: "Écrire une phrase que j'aimerais dire",
    yg_task_new: "Trouver un endroit pour rencontrer de nouvelles personnes",
    yg_task_old: "Envoyer « j'ai pensé à toi » à quelqu'un",
    nm_time_hour: "Heure",
    nm_time_minutes: "Minutes",
    routine_time_taken: "Il y a déjà quelque chose à cette heure : {title}",
    faq_a_new_me_times: "Dans le questionnaire du début et, à tout moment, dans les réglages de New Me → « Heures des repas ». Si votre routine a déjà des heures de repas, elles sont reprises de là – et les repas de la routine peuvent être masqués, avec les repas New Me affichés à leur place. Sinon, choisissez combien de repas par jour (2 repas + une collation / 2 repas + un dîner léger / 2 repas + une collation + un dîner léger) et l'heure de chacun. Avec « 2 repas + une collation », ce sont le déjeuner à 11:30, une collation à 16:00 et le dîner à 19:00 (chacun peut être changé). Ce sont vos heures de repas partout : dans le couloir, dans Ma Journée, dans Ma Routine et dans les rappels. Quel que soit le choix, les calories de la journée restent les mêmes : ce qui est retiré est réparti entre les autres repas.",
    faq_q_new_me_times: "Comment fixer mes heures de repas dans New Me ?",
    nm_times_count: "Combien de repas par jour ?",
    nm_times_from_routine: "Oui, les prendre dans ma routine",
    nm_times_hide: "Masquer les repas de ma routine et afficher à leur place les repas New Me",
    nm_times_later: "Plus tard",
    nm_times_manual: "Non, choisir ici",
    nm_times_none_found: "Votre routine n'a pas encore de repas : choisissez ici combien et à quelle heure.",
    nm_times_q: "Votre routine a-t-elle des heures fixes pour manger ?",
    nm_times_saved: "Heures des repas enregistrées",
    nm_times_title: "Heures des repas",
    faq_a_routine_exact_time: "Oui. Quand tu décris une routine à l'IA avec une heure précise (comme « 16:10 trading »), elle est enregistrée telle quelle, sans être arrondie à l'heure pile. Tout ce qui est noté dans ta routine s'affiche toujours sur le tableau, même si son heure n'est pas choisie dans les réglages des heures, et retirer une heure qui contient quelque chose demande d'abord confirmation. Tu peux aussi changer une heure à la main : touche l'heure dans la fenêtre de l'élément, puis choisis l'heure et les minutes.",
    faq_q_routine_exact_time: "Ma routine peut-elle avoir une heure précise, comme 16:10 ?",
