    routine_daysoff_which: "Quels jours ?",
    faq_a_secret_room_diary: "Personne d'autre que vous. Les pages du journal sont enregistrées dans votre compte : elles sont sur tous vos appareils et personne d'autre ne peut les voir. Il s'ouvre depuis le journal magique posé sur le bureau de la chambre secrète, et aussi depuis le journal du coin musique. Sous la nouvelle page, il y a un tableau mensuel replié : un point marque chaque jour qui a une page, et toucher un jour ouvre ses pages ; on peut aussi y supprimer une page. Une fois le journal ouvert, il peut aussi être ajouté au menu principal, avec l'interrupteur du journal lui-même ou dans les réglages de New Me.",
    faq_a_secret_room_places: "Chaque entrée du portail de la forêt s'ouvre avec sa propre clé. Derrière : le porche face à la mer (sur la petite table, la lampe d'Aladin – un toucher, et un esprit de la forêt en sort dans une brume magique, tourbillonne et commence une conversation sur votre vœu – voir « Que fait le génie de la lampe ? »), la guitare et le journal (la guitare joue un air court et calme et s'arrête toute seule, et chacun des trois disques suspendus dans l'arbre joue son propre air magique – touchez encore pour arrêter – et le journal posé sur la souche sert à écrire), la pièce pour respirer (un lac tranquille au coucher du soleil : une lanterne de lotus flotte sur l'eau – touchez-la, écrivez un vœu, et elle s'éloigne avec lui, loin au fond du lac ; avec la baguette magique, vous pouvez écrire dans le sable ce que vous voulez laisser partir, et ça reste jusqu'à ce que vous l'effaciez du doigt) et le sentier dans la forêt (il s'ouvre la nuit, et toucher les lanternes fait passer au jour ; le banc sert à s'asseoir, et toucher le panneau le rapproche : un tableau avec six petites questions à cocher). Une entrée fermée indique combien de clés il reste. Au bout du sentier, un portail lumineux mène au yoga près de la cascade – et de là, à la cascade elle-même.",
    faq_q_secret_room_diary: "Qui voit le journal ?",
    faq_q_secret_room_places: "Qu'y a-t-il derrière les portes du couloir ?",
