    ai_chat_ask_food: "Qu'avez-vous mangé ? Écrivez librement, par ex. « 2 tranches de pain avec du fromage »",
    ai_chat_ask_schedule: "Que faut-il mettre dans le calendrier ? Écrivez librement, par ex. « examen dimanche à 9 h »",
