    ai_chat_title: "Assistant",
    ai_chat_tool_food: "🍎 Ce que j'ai mangé",
    ai_chat_tool_photo: "📷 Photo d'une recette",
    ai_chat_tool_schedule: "📅 Quelque chose pour le calendrier",
    ai_chat_tool_table: "🗂️ Un nouveau tableau",
    ai_chat_working_food: "Un instant, je compte les calories…",
    ai_chat_working_schedule: "Un instant, j'ajoute au calendrier…",
    ai_chat_working_table: "Un instant, je crée le tableau…",
    dev_weather_preview_label: "Aperçu – uniquement sur votre compte :",
    faq_a_ai_chat: "Touchez la bulle et une discussion s'ouvre. Choisissez quoi faire – quelque chose pour le calendrier, ce que vous avez mangé, une photo de recette ou un nouveau tableau – ou écrivez simplement, et l'assistant comprend tout seul. Vous pouvez aussi toucher 🎙️ et parler au lieu d'écrire. Pour le calendrier, vous pouvez choisir une fois, chaque semaine ou chaque jour. La réponse arrive dans la discussion, et de là vous pouvez passer à autre chose ou ouvrir le calendrier / ce que vous avez mangé.",
    faq_a_new_me_hall: "New Me s'ouvre sur le portail d'une forêt magique, et chaque entrée y est un lieu : la porte ronde de l'arbre géant mène à la chambre secrète, le tronc creux au porche face à la mer, la maison-champignon à la guitare et au journal, la petite arche de saule à la pièce pour respirer, la grande arche de saule au sentier dans la forêt, et l'arche de fleurs avec l'échelle monte au toit des étoiles une fois celui-ci ouvert. Une entrée fermée affiche un cadenas. Votre personnage, Sky, flotte au-dessus du sentier, et les boutons du jeu sont tout autour : la prochaine mission, le défi de la semaine, le sac magique avec tout New Me, la carte du monde et les outils. Toucher les clés en haut explique comment on gagne des clés.",
    faq_a_new_me_routine_meals: "Quand des repas sont définis dans New Me et que Ma Routine contient aussi des repas, New Me demande s'il faut les masquer et afficher à leur place les repas New Me – pour que rien n'apparaisse deux fois. Ma Routine affiche alors les repas New Me à leurs heures, avec 💎 et un ✓ ; toucher le nom d'un repas ouvre une fenêtre pour choisir un autre repas ou changer son heure, directement là, au-dessus de la routine. Rien n'est supprimé : ils reviennent depuis ⚙️ Réglages de New Me → Repas dans la routine, ou en désactivant « Synchroniser avec New Me » dans le ⚙️ de Ma Routine. Sans New Me actif, ils reviennent d'eux-mêmes.",
    faq_a_room_computer: "C'est une petite discussion qui commence par « Comment se passe votre journée jusqu'ici ? » – bonne, chargée ou difficile – et qui avance avec vous pas à pas, jusqu'à une petite mission à la fin (qui peut aussi aller directement dans Ma Journée). On peut toucher les réponses ou écrire librement – ce qui est écrit est relié à la réponse la plus proche. « ↩ Retour » revient d'une étape pour répondre autrement, et « Nouvelle discussion » recommence à tout moment. Après une journée chargée ou difficile, vous pouvez revenir à l'ordinateur plus tard le même jour : « Je suis de retour... » reprend la conversation. Le voyant vert en bas éteint et rallume l'ordinateur. Seuls les choix sont conservés, uniquement sur cet appareil et seulement jusqu'à la fin de la journée.",
    faq_q_ai_chat: "Comment parler à l'assistant ?",
    faq_q_new_me_hall: "C'est quoi, le couloir de New Me ?",
    faq_q_new_me_routine_meals: "Pourquoi Ma Routine affiche-t-elle les repas New Me ?",
    faq_q_room_computer: "Comment fonctionne l'ordinateur de la chambre secrète ?",
