    dictation_btn_aria: "Parlez, c'est écrit",
    dictation_mic_denied: "Le micro est bloqué : autorisez-le depuis le 🔒 à côté de l'adresse, ou dans les réglages du téléphone",
    faq_a_dictation: "Oui : touchez le micro 🎤 dans le coin de la note rapide ou d'une page d'écriture du carnet, et parlez : les mots s'écrivent pendant que vous parlez, dans la langue de l'app. Touchez-le à nouveau pour arrêter. La première fois, le navigateur demande l'autorisation d'utiliser le micro. Fonctionne dans Chrome / Android et dans Safari sur iPhone. Sur ordinateur, il faut un micro et un navigateur comme Chrome, Edge ou Safari ; s'il manque quelque chose, le message dit exactement quoi.",
    faq_q_dictation: "Puis-je parler au lieu de taper ?",
    faq_a_secret_room: "Une pièce rien qu'à vous, dans New Me – une maison à l'intérieur d'un arbre géant. Vous voyez un mur à la fois et vous tournez avec les flèches (ou en glissant). La première clé arrive après un ✓ sur un repas 3 jours différents et ouvre la porte – et toute la pièce avec : l'ordinateur, le jeu, le tourne-disque, l'étagère avec la bibliothèque dedans et le chat. Ensuite, chaque défi terminé (le défi de la semaine aussi) donne une clé qui ouvre le lieu suivant : le toit des étoiles, le porche face à la mer, la guitare et le journal, la pièce pour respirer, le sentier dans la forêt avec le yoga, la cascade et une surprise sur le toit – et le 8e apporte une bouteille venue de la mer, avec la lettre du passé à l'intérieur. Quand quelque chose s'ouvre, une flèche montre le chemin. La petite porte en bas de la borne de jeu s'ouvre aussi – pour l'instant, le petit meuble derrière est vide. Sur le toit des étoiles, une étoile touchée tombe comme une étoile filante, et le chat est assis sur le coussin.",
