    settings_good_things_label: "« 3 bonnes choses » le soir",
    settings_weather_hint: "Pluie, nuages ou neige en fond d'écran d'accueil, selon la météo là où vous êtes. Votre position approximative reste sur cet appareil et est vérifiée via notre serveur auprès de MET Norway.",
    settings_weather_label: "La météo dans le ciel de l'écran d'accueil",
    weather_failed: "Impossible de vérifier la météo pour le moment.",
    weather_location_denied: "Pas d'accès à votre position – autorisez-la dans les réglages du navigateur et réessayez.",
    faq_a_home_focus: "Touchez ◎ en haut de l'écran d'accueil : tout disparaît sauf la seule chose du moment – ce qui se passe à cette heure-ci, ou la prochaine chose de la liste du jour – avec un grand ✓, et Note Rapide. Après le ✓, la chose suivante apparaît. Touchez « Mode concentration ✕ » en haut pour tout retrouver.",
    faq_a_home_search: "Ouvrez le menu ☰ : la recherche est tout en haut. Tapez au moins 2 lettres : les résultats viennent de vos notes, liste de courses, calendrier, recettes, carnets (titres et texte des pages), objectifs, tableaux et livres, regroupés par type – touchez-en un pour y aller directement.",
    faq_a_my_day: "Ma Journée réunit ce qui était Un Coup d'Œil sur Aujourd'hui et Ma Routine, sur une seule ligne du temps. En bas de l'écran d'accueil, vous voyez ce qui est fait, ce qui est en cours ou à venir (avec un ✓ rapide) et, à côté du titre, un verre d'eau en +1. Touchez-la (ou faites-la glisser vers le haut) pour ouvrir toute la journée : en haut ce qui n'a pas d'heure, puis tout par heure – tâches, événements et réunions du calendrier, créneaux fixes de la semaine, la routine du jour, les petits pas de vos objectifs et les repas New Me – avec une ligne pour maintenant. Filtrez par Tâches, Routine ou Rendez-vous et événements. Un ✓ ici est le même ✓ partout ailleurs (Ma Routine, Mes Objectifs, le calendrier) et ouvre une pâquerette dans le coin. « Modifier ma routine » ouvre Ma Routine (aussi dans le menu) et « ＋ Ajouter pour aujourd'hui » ajoute une tâche pour aujourd'hui. Un appui sur le titre « Ma Journée » (ou sur la petite barre en haut) le referme.",
    faq_q_home_focus: "Qu'est-ce que le mode concentration ?",
    faq_q_home_search: "Comment rechercher dans toute l'appli ?",
