    faq_a_new_me_tour: "Juste après l'achat et le court questionnaire, une petite visite montre le jeu : la barre du haut, la prochaine mission, le défi de la semaine, le sac magique et la porte 1 vers la chambre secrète. On peut la revoir à tout moment depuis ⚙️ Réglages > 🧭 Visite de New Me – le nom complet du questionnaire peut aussi y être modifié. Avant l'achat, New Me affiche un 🔒 dans le menu, et un toucher ouvre une page avec tout ce qui est inclus.",
