    faq_a_new_me_advanced: "Le Mode avancé s'ouvre avec le cadeau, après les 20 défis, et peut être activé ou désactivé dans 🎁 Votre cadeau. Il donne à New Me un look doré, un menu libre – chaque changement montre toutes les options sans limite de calories – et un écran 📊 Statistiques avancées : les calories des 30 derniers jours face au programme, les bonnes journées par jour de la semaine, la tendance du poids avec une estimation de la date d'arrivée à l'objectif, les moyennes du bilan du soir et l'historique des défis.",
