    nm_gift_intro: "Les {n} défis, pas à pas. Voici ce qui attendait :",
    nm_gift_title: "Votre cadeau",
    faq_a_new_me_letter_gift: "Au début de New Me (ou plus tard, dans Défis), on peut écrire une lettre à soi-même dans le futur. Une fois scellée, elle ne peut être ni lue ni modifiée avant de s'ouvrir : dans la bouteille venue de la mer, dans la chambre secrète, ou à la fin des 20 défis – où un cadeau attend aussi.",
    faq_q_new_me_letter_gift: "Qu'est-ce que la lettre du passé ?",
    faq_a_new_me_challenges: "🏆 Défis propose 20 défis : 10 grands (par exemple 5 jours sans sucre, une semaine sans glucides, ou perdre 4 kg en un mois – déficit calorique, sport et pas de sucre chaque jour) et 10 mini – de petites habitudes pendant une semaine, comme un café à la cannelle sans sucre. En choisissant un défi, on indique quand commencer : aujourd'hui, demain, la semaine prochaine ou une autre date. Un grand défi et un mini-défi peuvent se dérouler en même temps. Le défi en cours apparaît en haut du menu et dans Ma Journée, avec un ✓ pour la journée. Chaque semaine de défi offre un jour libre (🍕) qui ne le casse pas, et un jour non coché compte comme jour libre – on peut cocher aujourd'hui et aussi hier. Certains jours se cochent tout seuls : une séance de 20 minutes dans le Suivi des Entraînements, ou les repas du menu avec ✓. Chaque défi a un ⓘ avec ce qui compte exactement (par exemple la liste complète des glucides) – dans le défi lui-même et à côté, dans Ma Journée. En dessous, 🌱 Développement personnel propose 48 petits défis d'une semaine (ils ne comptent pas dans les 20) – voir « Qu'est-ce que le défi de la semaine ? ».",
    faq_q_new_me_challenges: "Comment fonctionnent les défis de New Me ?",
    nm_letter_too_short: "Encore quelques mots 🙂",
    nm_letter_quiz_note: "Facultatif – elle peut aussi être écrite plus tard, dans Défis.",
    nm_letter_write: "✍️ Écrire la lettre",
    nm_letter_sealed_line: "Scellée le {date} · s'ouvre après les {n} défis",
    nm_letter_sealed_toast: "Scellée ✉️ – rendez-vous à l'arrivée",
    nm_letter_seal_note: "Une fois scellée, la lettre ne peut être ni lue ni modifiée avant la fin de tous les défis.",
    nm_letter_seal: "✉️ Sceller la lettre",
    nm_letter_ph: "Où j'en suis aujourd'hui, ce que je veux atteindre, ce qui est difficile pour moi avec la nourriture, ce que j'aimerais me dire à l'arrivée…",
    nm_letter_intro: "Écrite maintenant et scellée – elle ne s'ouvre qu'après les {n} défis, pour voir tout ce qui a changé depuis. Où j'en suis aujourd'hui ? Quels sont mes objectifs, et qu'est-ce qui est difficile pour moi avec la nourriture ?",
