    nm_ch_completed_label: "défis réussis",
    nm_tile_challenges: "Défis",
    faq_a_workout_calories: "Oui. Chaque entraînement reçoit une estimation des calories brûlées – selon le type, la durée et votre dernier poids (pour la course et le vélo aussi selon la vitesse, quand une distance est saisie). Elle apparaît dans la liste des entraînements et dans le bilan mensuel (Brûlées), et s'ajoute au budget de calories de ce jour : dans le Suivi Quotidien des Repas, dans Métriques de Calories et de Poids et dans l'anneau de New Me. C'est une estimation, d'où le ~.",
    faq_q_workout_calories: "Les entraînements comptent-ils dans mes calories du jour ?",
    faq_a_new_me_flexible_menu: "Oui. Dans le questionnaire et dans les réglages, on choisit le nombre de repas par jour – 2 repas + une collation / 2 repas + un dîner léger / 2 repas + une collation + un dîner léger – et ➖ sur la carte d'un repas le retire (au moins 3 restent) ; « Remettre » le fait revenir. Dans tous les cas, les calories de la journée restent les mêmes : ce qui est retiré est réparti entre les autres repas, et chaque repas indique ce qui lui a été ajouté et ce qu'on peut y mettre. ✏️ Modifier sur un repas ouvre son texte – changez ce que vous voulez (par ex. sans pain, ou un œuf de plus) et l'IA recalcule les calories et les protéines. 🔄 Changer propose des options du menu, ⭐ Enregistrés et ✨ L'écrire ; chaque changement peut valoir pour aujourd'hui seulement ou à partir de maintenant. Et à la fin de « Toute la journée », il y a ➕ Ajouter un aliment – écrivez ce qui a été mangé hors du menu, l'IA le calcule et l'ajoute à aujourd'hui (✕ le supprime).",
    faq_q_new_me_flexible_menu: "Puis-je changer le nombre de repas dans New Me, ou manger mon propre repas ?",
    daily_calorie_mini_burn: "+🔥 {amount} d'entraînement",
    calorie_burn_line: "🏃 {amount} kcal d'entraînement – ajoutées au budget du jour ({budget})",
    sport_total_kcal: "Brûlées",
    nm_swap_ai_too_big: "Un peu plus que ce qui reste pour aujourd'hui – jusqu'à ~{n} kcal rentrent. Vous pouvez quand même l'enregistrer – les autres repas du jour deviennent plus petits pour équilibrer – ou choisir une portion plus petite.",
