    nm_swap_ai_hint: "Écrivez ce que vous aimeriez manger, avec les quantités si possible – les calories et les protéines sont estimées pour vous.",
    nm_swap_saved_empty: "Pas encore de repas enregistrés – ils s'ajoutent dans le Suivi Quotidien des Repas (⭐ / 💾)",
