    goal_share_heading: "J'ai atteint un objectif !",
    share_footer_sent_from: "Envoyé depuis NOT10.ai",
    faq_a_goal_days_challenge: "Dans Mes Objectifs, appuyez sur ＋ (ou sur l'exemple prêt à l'emploi '🔥 8 jours'), choisissez '📆 Défi quotidien', indiquez le nombre de jours et ajoutez ce que vous faites chaque jour (ex. '30 minutes de marche', 'Manger selon mon menu'). Chaque jour, cochez les tâches du jour sous le chemin du défi – quand elles sont toutes cochées, la journée compte, le chemin avance d'une pierre et votre série 🔥 s'allonge (sans tâches quotidiennes, il y a un seul bouton '✓ Je l'ai fait aujourd'hui'). Le bouton 🔁 à côté d'une tâche l'ajoute à Ma Routine à l'heure de votre choix : la cocher là-bas la coche aussi dans l'objectif, et inversement. Les étapes d'un objectif classique peuvent être ajoutées à Ma Routine de la même façon.",
