    vision_focus_ribbon: "🎯 Objectif du mois",
    vision_tagline: "Grands objectifs, petits pas.",
    faq_a_app_tour: "La visite s'ouvre automatiquement une fois, lors de votre première connexion. Elle commence par ses parties – touchez-en une pour y aller directement – puis montre toutes les parties de l'appli (l'écran d'accueil, l'assistant IA et chaque élément du menu) et les cinq groupes des Paramètres, chacun avec une courte explication, et jette un œil à l'intérieur de certains (par exemple un parcours d'objectif d'exemple, le sac et Google Calendar). Continuer avance, Retour revient en arrière, Passer cette partie saute à la partie suivante et ✕ ferme la visite. Vous pouvez la revoir à tout moment depuis Paramètres > Aide et utilisation > Visite guidée, et reprendre là où vous en étiez. Continuer et Retour restent toujours au même endroit, en bas de l'écran, et sur ordinateur les flèches du clavier fonctionnent aussi.",
    faq_q_app_tour: "Comment revoir la visite guidée de l'app ?",
    apptour_done_text: "Une question ? Aide et FAQ, dans les Paramètres, répond à tout, et cette visite est toujours disponible dans Aide et utilisation.",
