    apptour_s_support_text: "Aide et FAQ, nous contacter, partager l'app – et cette visite, à tout moment.",
    apptour_s_account_text: "Premium, mot de passe, rapport personnel en PDF, synchronisation Google Calendar et suppression du compte.",
    apptour_s_notifications_text: "Les notifications de rappel et leur son. « ⏰ Pas encore » sur un rappel fonctionne comme le bouton snooze d'un réveil : un nouveau rappel arrive toutes les 5 minutes.",
    apptour_s_personalization_text: "Pays, repas et collations par jour, début de votre mois financier, et ce qui s'affiche sur l'écran d'accueil.",
    apptour_s_appearance_text: "Langue, mode clair ou sombre, thèmes, police, couleur du texte, accessibilité et taille de l'app.",
    apptour_m_style_text: "Ce bouton passe le menu en grandes tuiles – et inversement. Un seul des deux apparaît sur l'écran d'accueil.",
    apptour_m_style_title: "Liste ou tuiles",
    apptour_m_receipts_link: "Exportez une catégorie en PDF, ou totalisez tout par années avec 🧮.",
    apptour_m_receipts_text: "Conservez factures et reçus avec photos, à usage personnel ou professionnel.",
    apptour_m_budget_link: "Paiements échelonnés et prélèvements automatiques (avec import Excel), vos propres catégories et un jour de réinitialisation du budget dans les Paramètres.",
    apptour_m_budget_text: "Dépenses et revenus par catégorie, avec un solde mensuel.",
