    apptour_m_notes_text: "Notes et idées dans une seule liste.",
    apptour_m_tables_link: "L'Assistant IA peut concevoir un tableau automatiquement.",
    apptour_m_tables_text: "Des tableaux personnels – cadeaux, séries, listes – avec des colonnes texte, nombre, sélection, date et ✓ (Premium).",
    apptour_m_study_link: "🪄 La Répartition intelligente, dans la carte ✅ Tâches, découpe une grosse tâche en étapes dans votre calendrier.",
