    apptour_ai_food_link: "Va directement dans le Suivi Quotidien des Repas et le total du jour.",
    apptour_ai_food_text: "Saisissez ce que vous avez mangé – les calories sont estimées et enregistrées pour vous.",
    apptour_newme_short_text: "Ouvre New Me – le menu du jour est directement sur l'écran principal.",
