    apptour_quicknote_link: "📝 et 🛒 ouvrent les listes complètes ; 🍎 ajoute un repas enregistré au Suivi Quotidien des Repas.",
    apptour_quicknote_text: "Notez quelque chose en vitesse – dans vos Notes ou directement sur la Liste de Courses.",
    apptour_routine_link: "Une habitude peut enregistrer automatiquement un entraînement dans le Suivi des Entraînements.",
    apptour_routine_text: "Votre routine quotidienne heure par heure, en onglets (enfants, études, travail…). Cochez ✓ chaque jour pour créer des habitudes et des séries ; 📅 affiche tout le mois.",
    apptour_premium_text: "Débloque l'assistant IA complet, les thèmes, les polices, Mon sac et plus encore.",
    apptour_note_text: "Un pense-bête pour toute la semaine. À l'intérieur, la roue dentée ⚙ ajoute une liste à cocher de 1–3 lignes et change sa couleur et son style.",
    apptour_peek_link: "Ici s'affichent les tâches de l'IA, du calendrier et de Google Calendar et les étapes de vos objectifs – ainsi que les calories du jour 🔥 et votre 🎯 objectif du mois.",
    apptour_peek_text: "Tout ce qui se passe aujourd'hui au même endroit : tâches, réunions, votre routine et les petits pas sur une seule ligne du temps. Cochez ✓ directement ici.",
