    table_select_option_delete_confirm: "Cette option est utilisée dans {count} lignes. La supprimer ? Ces cellules seront vidées.",
    table_select_option_delete_title: "Supprimer l'option",
    faq_a_other_manual_option: "Partout où vous choisissez dans une liste d'options, il y a aussi '✏️ Autre' : sélectionnez-la et tapez exactement ce dont vous avez besoin. Dans un tableau avec une colonne de choix (par exemple 'Lien de parenté' dans un tableau de cadeaux), touchez la cellule, choisissez '✏️ Autre', tapez la valeur (par exemple 'Neveu') et touchez Ajouter : elle est enregistrée comme nouvelle option de cette colonne, et la prochaine fois elle figure déjà dans la liste. Le petit × à côté de chaque option de cette liste supprime l'option de la colonne. Pour choisir l'icône d'un tableau, il y a de nombreuses icônes (dont des notes autocollantes colorées). Cela fonctionne de la même façon pour les catégories de repas enregistrés, les catégories de recettes, les catégories de dépenses récurrentes (enregistrée comme nouvelle catégorie personnelle) et les catégories d'objectifs dans Mes Objectifs.",
    faq_q_other_manual_option: "L'option dont j'ai besoin n'est pas dans la liste - que faire ?",
