    receipts_total_title: "Total de tous les reçus",
    receipts_total_tile: "Total de tous les reçus",
    faq_a_quick_note_apple: "La 🍎 à côté de 📝 et 🛒 dans la fenêtre de notes est un raccourci pour ajouter rapidement l'un de vos repas enregistrés au Suivi Quotidien des Repas du jour. Elle est activée par défaut - si vous n'en avez pas besoin, désactivez-la dans Paramètres > Personnalisation et calendrier ('Afficher le raccourci 🍎 vers les repas enregistrés dans la fenêtre de notes'), et réactivez-la au même endroit à tout moment.",
    faq_q_quick_note_apple: "Qu'est-ce que la 🍎 dans la fenêtre de notes, et peut-on la masquer ?",
    settings_quick_note_apple_label: "Afficher le raccourci 🍎 vers les repas enregistrés dans la fenêtre de notes",
    faq_a_vision_board_today: "Dans Mes Objectifs, sous le chemin d'un objectif (dans « Le plan »), appuyez sur 📅 à côté d'une étape et choisissez une date. Vous pouvez aussi activer « 🔁 Chaque semaine jusqu'à ce que ce soit fait » – l'étape revient alors chaque semaine le même jour, tant que vous ne l'avez pas cochée. Elle apparaît ce jour-là dans Ma Journée et dans le calendrier (ainsi que dans Google Calendar, s'il est connecté), et le bouton indique quand elle est planifiée. Un ✓ d'un côté coche aussi l'autre et fait avancer le chemin de l'objectif. Appuyez à nouveau sur 📅 pour changer la date ou la retirer du calendrier. Supprimer du calendrier une tâche ponctuelle supprime aussi l'étape de l'objectif ; supprimer une semaine d'un rappel hebdomadaire ne retire que cette semaine.",
    faq_q_vision_board_today: "Comment mettre une étape d'objectif dans le calendrier (📅) ?",
    vision_milestone_already_today: "Cette étape figure déjà dans les tâches du jour.",
