    auth_consent_label: "J'ai lu et j'accepte les {terms} et la {privacy}, et j'ai 16 ans ou plus.",
    nm_bonus_sub: "Une courte lecture sur la pesée, le dépassement de l'objectif et les repas à l'extérieur",
