    nm_drink_more: "+ Autre boisson",
    nm_drink_add: "Ajouter",
    nm_drink_name_ph: "Boisson (ex. jus)",
    nm_drinks_hint: "Il suffit de saisir la boisson – les calories sont calculées automatiquement, et le nombre peut être modifié.",
    nm_slot_drinks: "Boissons",
    faq_a_new_me_tracking: "Touchez la prochaine mission en haut de New Me, puis ✓ J'ai mangé pour indiquer que le prochain repas a été mangé – le menu complet avec ✓ sur chaque repas se trouve dans Toute la journée, sur le côté, et les repas du jour apparaissent aussi dans Ma Journée sur l'écran d'accueil – toucher l'un d'eux à cet endroit (ou le survoler avec la souris) montre exactement quoi manger, avec ✓ et Changer. Tout est synchronisé avec le Suivi Quotidien des Repas : les repas du programme, les boissons et tout ce que vous ajoutez ailleurs (par exemple un café via l'ajout rapide) sont comptés ensemble dans New Me et dans Ma Journée – rien de ce que vous avez déjà saisi n'est écrasé, et retirer un ✓ ne retire que la partie New Me. Quand tous les repas du jour sont cochés, il y a une petite fête. Dans « Boissons », notez les boissons du jour – en tout jusqu'à ~150 kcal, soit environ 3 boissons de ~50 kcal maximum chacune. Il suffit d'écrire le nom de la boisson et les calories sont remplies automatiquement par l'IA. Les deux lignes café/thé ont aussi un champ « Du lait ? Combien ? » (par exemple « un peu » ou « 50 ml »), et le calcul se met à jour ; le nombre peut être modifié avant l'ajout et aussi après. Une boisson avec un nom et des calories est enregistrée automatiquement dès que vous passez à autre chose – toucher Ajouter est facultatif. Touchez ☆ à côté d'une boisson pour l'enregistrer comme boisson habituelle – les boissons habituelles apparaissent comme boutons en haut de la carte Boissons, et un toucher les ajoute à la journée. ⭐ enregistre un repas comme repas enregistré. « Tableau du jour » montre ce que vous avez mangé avec les calories et les protéines. Le petit 💎 à côté du mode concentration, en haut de l'écran d'accueil, l'ouvre directement. Les valeurs de calories et de protéines sont des estimations de l'IA et peuvent contenir des erreurs. Pas tout mangé ? Sous un repas coché, « Pas tout mangé ? » retire un quart, la moitié ou trois quarts de la portion – ou ce que vous écrivez, calculé – et les calories du jour se mettent à jour.",
    faq_q_new_me_tracking: "Comment fonctionnent le ✓, les changements et les calories dans New Me ?",
    faq_a_new_me_what: "New Me est un programme de menus quotidiens à part, avec deux plans prêts – 1 300 ou 1 500 calories – composés de 2 repas principaux et 2 collations, avec 3 options pour chacun. Il inclut tout Premium. Prix : 11,99 $ par mois (résiliable à tout moment) ou 99,99 $ une seule fois, à vie. On l'ouvre depuis 💎 New Me dans le menu. Avant de commencer, un court questionnaire débute par un avertissement médical à accepter. Le programme est une information générale et ne remplace pas un médecin ni un diététicien clinique.",
    faq_q_new_me_what: "Qu'est-ce que New Me et comment l'obtenir ?",
