    food_ai_estimating: "Estimation en cours...", food_clarify_title: "Encore une petite question", food_clarify_placeholder: "Tapez votre réponse...", food_ai_unknown_toast: "Impossible d'identifier cela avec certitude - une estimation approximative a été enregistrée à la place. Essayez de le décrire différemment pour un résultat plus précis.",
