    daily_focus_modal_title: "🧠 Quelle est la chose la plus importante à faire aujourd'hui ?", daily_focus_modal_subtitle: "Répondez, et ce sera ajouté directement au planning d'aujourd'hui.", daily_focus_input_placeholder: "Aujourd'hui, je veux surtout", daily_focus_save_btn: "Ajouter au planning d'aujourd'hui", daily_focus_skip_btn: "Pas maintenant", daily_focus_missing_text: "Écrivez d'abord quelque chose", daily_focus_added_toast: "Ajouté au planning d'aujourd'hui", daily_focus_other_option: "✍️ Autre...",
    daily_focus_c1_d0: "Protéger mon espace de calme face au bruit ambiant", daily_focus_c1_d1: "Poser des limites claires, avec amour et sans culpabilité", daily_focus_c1_d2: "Garder mon ancrage même quand la tempête gronde autour de moi", daily_focus_c1_d3: "Faire de mon calme et de mon énergie ma priorité absolue", daily_focus_c1_d4: "Ne pas porter les émotions et les humeurs des autres", daily_focus_c1_d5: "Ne pas laisser les mots des autres ébranler ma valeur personnelle",
    daily_focus_c2_d0: "Écouter ce dont mon corps et mon esprit ont besoin", daily_focus_c2_d1: "Savourer les petites choses en chemin", daily_focus_c2_d2: "Ralentir et vraiment me reconnecter à moi-même", daily_focus_c2_d3: "Me laisser de la place pour respirer au milieu de l'action", daily_focus_c2_d4: "Me sentir chez moi et en paix avec moi-même", daily_focus_c2_d5: "Me concentrer sur l'instant présent, sans me précipiter vers la suite",
