    faq_q_daily_focus_prompt: "Quel est ce petit rappel qui me demande ce qui est le plus important à faire aujourd'hui ?", faq_a_daily_focus_prompt: "C'est un rappel quotidien Premium : une fois par jour, un petit badge « 1 » apparaît sur l'icône de l'assistant IA. Touchez le badge pour ouvrir une bulle qui vous demande ce qui compte le plus pour vous aujourd'hui, avec tout de suite 5 suggestions toutes prêtes (elles changent chaque jour et tournent sur toute une année de thèmes différents pour rester variées) plus 'Autre' pour écrire la vôtre ; vous pouvez en choisir plusieurs. Touchez Ajouter, et vos choix s'affichent sous forme de petites étiquettes de rappel en haut de 'Ma Journée' (ce ne sont pas des tâches à cocher). Si vous le fermez avec ✕ ou touchez à l'extérieur, le badge s'estompe simplement pour le reste de la journée au lieu de disparaître. Il est activé par défaut, mais vous pouvez le désactiver dans Paramètres > Personnalisation et calendrier. Pas le bon jour ? Touchez « 🌙 Pas aujourd'hui » : le badge disparaît jusqu'à demain, et la question revient comme d'habitude. Une des suggestions vient de votre propre vie – la prochaine étape de votre objectif du mois ou la lecture du jour. Chaque jour est un nouveau départ.",
